//! Absolute/self-relative SECURITY_DESCRIPTOR conversion using caller-owned storage.
use super::acl::{RtlAcl,RtlSecurityDescriptor};
use super::sid::SidHeader;
const SUCCESS:i32=0;const INVALID:i32=0xC000000Du32 as i32;const SMALL:i32=0xC0000023u32 as i32;const BAD_SD:i32=0xC0000079u32 as i32;
const SELF:u16=0x8000;
unsafe fn sid_len(s:*const SidHeader)->usize{if s.is_null(){0}else{(unsafe{super::sid::rtl_length_sid(s)}) as usize}}
unsafe fn component_len(sd:*const RtlSecurityDescriptor,which:usize)->usize{let s=unsafe{&*sd};match which{0=>unsafe{sid_len(s.owner)},1=>unsafe{sid_len(s.group)},2=>if s.sacl.is_null(){0}else{unsafe{(*s.sacl).size as usize}},_=>if s.dacl.is_null(){0}else{unsafe{(*s.dacl).size as usize}}}}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_absolute_to_self_relative_sd(abs:*const RtlSecurityDescriptor,rel:*mut u8,length:*mut u32)->i32{if abs.is_null()||length.is_null()||unsafe{(*abs).revision!=1||(*abs).control&SELF!=0}{return BAD_SD;}let a=unsafe{&*abs};for p in [a.owner,a.group]{if !p.is_null()&&unsafe{super::sid::rtl_valid_sid(p)}==0{return BAD_SD;}}for p in [a.sacl,a.dacl]{if !p.is_null()&&unsafe{super::acl::rtl_valid_acl(p)}==0{return BAD_SD;}}let mut total=20usize;let mut offs=[0u32;4];for i in 0..4{let n=unsafe{component_len(abs,i)};if n!=0{total=(total+3)&!3;offs[i]=total as u32;total=total.saturating_add(n);}}if total>u32::MAX as usize{return SMALL;}let cap=unsafe{*length} as usize;unsafe{*length=total as u32;}if rel.is_null()||cap<total{return SMALL;}unsafe{core::ptr::write_bytes(rel,0,total);*rel=a.revision;*(rel.add(2) as *mut u16)=a.control|SELF;for i in 0..4{*(rel.add(4+i*4) as *mut u32)=offs[i];}for i in 0..4{if offs[i]==0{continue;}let n=unsafe{component_len(abs,i)};let src:*const u8=match i{0=>a.owner as *const u8,1=>a.group as *const u8,2=>a.sacl as *const u8,_=>a.dacl as *const u8};core::ptr::copy_nonoverlapping(src,rel.add(offs[i] as usize),n);}}SUCCESS}
#[unsafe(no_mangle)] pub unsafe extern "win64" fn rtl_self_relative_to_absolute_sd(rel:*const u8,abs:*mut RtlSecurityDescriptor,abs_len:*mut u32,dacl:*mut RtlAcl,dacl_len:*mut u32,sacl:*mut RtlAcl,sacl_len:*mut u32,owner:*mut SidHeader,owner_len:*mut u32,group:*mut SidHeader,group_len:*mut u32)->i32{
 if rel.is_null()||abs_len.is_null()||dacl_len.is_null()||sacl_len.is_null()||owner_len.is_null()||group_len.is_null(){return INVALID;}let control=unsafe{*(rel.add(2) as *const u16)};if unsafe{*rel}!=1||control&SELF==0{return BAD_SD;}let mut required=[0usize;4];let mut offsets=[0u32;4];for i in 0..4{offsets[i]=unsafe{*(rel.add(4+i*4) as *const u32)};if offsets[i]!=0{let o=offsets[i] as usize;if o<20{return BAD_SD;}if i<2{let p=unsafe{rel.add(o) as *const SidHeader};required[i]=unsafe{sid_len(p)};if required[i]==0{return BAD_SD;}}else{let p=unsafe{rel.add(o) as *const RtlAcl};let n=unsafe{(*p).size as usize};if n<8{return BAD_SD;}required[i]=n;}}}
 let abs_capacity=unsafe{*abs_len} as usize;let caps=[unsafe{*owner_len} as usize,unsafe{*group_len} as usize,unsafe{*sacl_len} as usize,unsafe{*dacl_len} as usize];unsafe{*abs_len=core::mem::size_of::<RtlSecurityDescriptor>() as u32;*owner_len=required[0] as u32;*group_len=required[1] as u32;*sacl_len=required[2] as u32;*dacl_len=required[3] as u32;}if abs.is_null()||core::mem::size_of::<RtlSecurityDescriptor>()>abs_capacity{return SMALL;}for i in 0..4{if required[i]>0&&(caps[i]<required[i]||[owner as *mut u8,group as *mut u8,sacl as *mut u8,dacl as *mut u8][i].is_null()){return SMALL;}}
 unsafe{if required[0]>0{core::ptr::copy_nonoverlapping(rel.add(offsets[0] as usize),owner as *mut u8,required[0]);}if required[1]>0{core::ptr::copy_nonoverlapping(rel.add(offsets[1] as usize),group as *mut u8,required[1]);}if required[2]>0{core::ptr::copy_nonoverlapping(rel.add(offsets[2] as usize),sacl as *mut u8,required[2]);}if required[3]>0{core::ptr::copy_nonoverlapping(rel.add(offsets[3] as usize),dacl as *mut u8,required[3]);}*abs=RtlSecurityDescriptor{revision:*rel,sbz1:*rel.add(1),control:control&!SELF,owner:if required[0]>0{owner}else{core::ptr::null_mut()},group:if required[1]>0{group}else{core::ptr::null_mut()},sacl:if required[2]>0{sacl}else{core::ptr::null_mut()},dacl:if required[3]>0{dacl}else{core::ptr::null_mut()}};}SUCCESS
}

